<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import Icon from './personal/Icon.vue'
import { ApiError, loadTasks, loadProjects, completeTask } from './fifones/api.js'
import { photoToDataUrl } from './personal/proof.js'
const sections=[
{id:'inicio',label:'Seu dia',icon:'home',group:'SEU ESPAÇO',description:'O que importa, sem carregar tudo na cabeça.'},
{id:'tarefas',label:'Tarefas',icon:'tasks',group:'SEU ESPAÇO',description:'Uma coisa de cada vez.'},
{id:'agenda',label:'Agenda',icon:'calendar',group:'SEU ESPAÇO',description:'Espaço para seus compromissos.'},
{id:'habitos',label:'Hábitos',icon:'habits',group:'EVOLUIR',description:'Pequenos passos. Uma vida inteira.'},
{id:'metas',label:'Metas',icon:'spark',group:'EVOLUIR',description:'Dê forma ao que você quer conquistar.'},
{id:'fitness',label:'Fitness',icon:'fitness',group:'EVOLUIR',description:'Sua trajetória, seu ritmo.'},
{id:'nutricao',label:'Alimentação',icon:'nutrition',group:'EVOLUIR',description:'Conheça o que faz parte do seu prato.'},
{id:'autoconhecimento',label:'Autoconhecimento',icon:'mind',group:'EVOLUIR',description:'Observe como você está. Sem julgamento.'},
{id:'estudos',label:'Estudos',icon:'study',group:'EVOLUIR',description:'Leia, pergunte e pratique.'},
{id:'financas',label:'Finanças',icon:'finance',group:'ORGANIZAR',description:'Clareza sobre o que entra e o que sai.'},
{id:'projetos',label:'Projetos',icon:'projects',group:'ORGANIZAR',description:'Transforme intenção em próximos passos.'},
{id:'biblioteca',label:'Biblioteca',icon:'library',group:'ORGANIZAR',description:'Seus materiais, sempre por perto.'},
{id:'memorias',label:'Memórias',icon:'note',group:'ORGANIZAR',description:'Guarde o que você quer levar adiante.'}]
const groups=[...new Set(sections.map(i=>i.group))]
const now=ref(Date.now())
const route=ref('inicio'), collapsed=ref(false), mobileMenu=ref(false), search=ref(''), taskFilter=ref('open')
const data=ref({entries:[],checkins:[],sources:{}}), tasks=ref([]), projects=ref([]), connected=ref(false), loading=ref(true), refreshing=ref(false), error=ref(''), notice=ref('')
const failedCovers=ref({})
const proofDialog=ref(null), proofSaving=ref(false)
const domains=[['saude','Saúde'],['alimentacao','Alimentação'],['financas','Finanças'],['estudos','Estudos'],['mente','Mente'],['organizacao','Organização']]
const routeDomain={fitness:'saude',nutricao:'alimentacao',financas:'financas',estudos:'estudos',biblioteca:'estudos',autoconhecimento:'mente'}
const modal=ref(null), saving=ref(false), bridge=ref(null), bridgeLoading=ref(false)
const form=ref({title:'',body:'',amount:'',direction:'expense',category:'pessoal',day:'',due_date:''})
let poll, timer, bridgeTimer, previousFocus
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(now.value))
const shortDate=computed(()=>new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',weekday:'long',day:'numeric',month:'long'}).format(new Date(now.value)))
const greeting=computed(()=>{const hour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'America/Sao_Paulo',hour:'2-digit',hourCycle:'h23'}).format(new Date(now.value)));return hour<12?'Bom dia, Luiz.':hour<18?'Boa tarde, Luiz.':'Boa noite, Luiz.'})
const active=computed(()=>sections.find(i=>i.id===route.value))
const entryList=kind=>data.value.entries.filter(i=>i.kind===kind)
const habits=computed(()=>entryList('habit'))
const goals=computed(()=>entryList('goal'))
const goalCount=id=>data.value.checkins.filter(i=>i.entry_id===id&&i.done===1).length
const isDone=ident=>data.value.checkins.some(i=>i.entry_id===ident&&i.day===today()&&i.done===1)
const habitsDone=computed(()=>habits.value.filter(i=>isDone(i.id)).length)
const pending=computed(()=>tasks.value.filter(i=>i.status!=='done'&&!i.completed_at))
const shownTasks=computed(()=>tasks.value.filter(i=>(taskFilter.value==='all'||(taskFilter.value==='open'?i.status!=='done':i.status==='done'))&&(!search.value||String(i.title).toLowerCase().includes(search.value.toLowerCase()))))
const routeSource=computed(()=>({agenda:'events',fitness:'fitness',biblioteca:'documents',estudos:'documents',memorias:'memories'})[route.value])
const sourceList=key=>Array.isArray(data.value.sources[key]?.data)?data.value.sources[key].data:[]
const events=computed(()=>sourceList('events')), documents=computed(()=>sourceList('documents')), memories=computed(()=>sourceList('memories'))
const fitness=computed(()=>data.value.sources.fitness?.data||{})
const todayEvents=computed(()=>events.value.filter(i=>String(i.start_at||'').slice(0,10)===today()))
const notes=computed(()=>entryList('note')), transactions=computed(()=>entryList('transaction'))
const monthTransactions=computed(()=>transactions.value.filter(i=>i.day.slice(0,7)===today().slice(0,7)))
const income=computed(()=>monthTransactions.value.filter(i=>i.direction==='income').reduce((s,i)=>s+i.amount_cents,0))
const expenses=computed(()=>monthTransactions.value.filter(i=>i.direction==='expense').reduce((s,i)=>s+i.amount_cents,0))
const money=cents=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(cents/100)
const formatDate=day=>day?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(day.slice(0,10)+'T12:00:00')):'Sem data'
const formatTime=value=>value?String(value).slice(11,16):''
const match=q=>!search.value||String(q||'').toLowerCase().includes(search.value.toLowerCase())
const filteredDocs=computed(()=>documents.value.filter(i=>match(i.name||i.filename||i.title)))
const upcoming=computed(()=>[...events.value].filter(i=>String(i.start_at||'').slice(0,10)>=today()).sort((a,b)=>String(a.start_at).localeCompare(String(b.start_at))))
const weeks=computed(()=>{const d=new Date(today()+'T12:00:00');const offset=(d.getDay()+6)%7;return Array.from({length:7},(_,i)=>{const n=new Date(d);n.setDate(d.getDate()-offset+i);const key=`${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`;return{day:key,num:n.getDate(),label:['S','T','Q','Q','S','S','D'][i],today:key===today()}})})
const areaCards=computed(()=>[
{id:'habitos',icon:'habits',tone:'mint',title:'Seja constante',value:habits.value.length?`${habitsDone.value} de ${habits.value.length}`:'Seu primeiro hábito',detail:habits.value.length?'passos dados hoje':'Comece com dois minutos'},
{id:'fitness',icon:'fitness',tone:'peach',title:'Cuide de você',value:fitness.value.weights?.length?`${fitness.value.weights[0].kg} kg`:'Sua evolução',detail:'Treino, trajetória e recuperação'},
{id:'financas',icon:'finance',tone:'purple',title:'Respire mais leve',value:transactions.value.length?money(income.value-expenses.value):'Sua vida financeira',detail:transactions.value.length?'saldo dos registros deste mês':'Entradas e saídas, com clareza'},
{id:'estudos',icon:'study',tone:'blue',title:'Continue aprendendo',value:`${documents.value.length} materiais`,detail:'Leia com o Fifones ao seu lado'}])
async function api(path, method = 'GET', body) {
  const res = await fetch(path, {
    method,
    headers: {
      Accept: 'application/json',
      ...(method !== 'GET' ? { 'Content-Type': 'application/json', 'X-Fifones-City': '1' } : {}),
    },
    ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
  })
  const value = await res.json().catch(() => null)
  if (!res.ok) {
    throw new ApiError(typeof value?.detail === 'string' ? value.detail : value?.message || 'Não foi possível salvar. Tente novamente.', res.status, value)
  }
  return value
}
function notify(text,kind='success'){notice.value={text,kind};clearTimeout(timer);timer=setTimeout(()=>notice.value='',4500)}
function parseRoute(){const id=location.hash.replace(/^#\/?/,'').split('/')[0];route.value=sections.some(i=>i.id===id)||id==='cidade'||id==='mundo'?id:'inicio';search.value='';mobileMenu.value=false;document.title=(route.value==='cidade'?'Minha cidade':route.value==='mundo'?'Mapa-mundo':active.value?.label||'Seu espaço')+' · Cityou'}
function navigate(id){location.hash='/'+id}
async function refresh() {
  if (refreshing.value) return
  refreshing.value = true
  now.value = Date.now()
  error.value = ''
  const [personal, taskResult, projectResult] = await Promise.allSettled([api('/api/personal'), loadTasks(), loadProjects()])
  if (personal.status === 'fulfilled') {
    data.value = personal.value
  } else {
    error.value = personal.reason?.status === 404
      ? 'Os registros pessoais precisam do servidor Cityou, que não está disponível neste endereço.'
      : 'Não foi possível carregar seus registros. Tente atualizar.'
  }
  if (taskResult.status === 'fulfilled') {
    tasks.value = taskResult.value.tasks || []
    connected.value = taskResult.value.connected
  } else {
    connected.value = false
  }
  if (projectResult.status === 'fulfilled') projects.value = projectResult.value.projects || []
  loading.value = false
  refreshing.value = false
}
function showForm(kind){previousFocus=document.activeElement;modal.value=kind;form.value={title:'',body:'',amount:'',direction:'expense',category:'pessoal',day:today(),due_date:'',target:1,domain:routeDomain[route.value]||'organizacao',place:''};nextTick(()=>document.querySelector('.entry-dialog input')?.focus())}
function closeForm(){if(saving.value)return;modal.value=null;previousFocus?.focus?.()}
async function save(){if(saving.value)return;saving.value=true;try{if(modal.value==='task'){await api('/api/personal/tasks','POST',{title:form.value.title,due_date:form.value.due_date||null,domain:form.value.domain,place:form.value.place});notify('Tarefa salva no seu Fifones.')}else{const raw=String(form.value.amount).trim().replace(/^R\$\s*/, '').replace(/\s/g,'');const normalized=/^\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?$/.test(raw)?raw.replace(/\./g,'').replace(',','.'):/^\d+(?:[,.]\d{1,2})?$/.test(raw)?raw.replace(',','.'):'invalid';const cents=Math.round(Number(normalized)*100);if(modal.value==='transaction'&&(!Number.isFinite(cents)||cents<1))throw Error('Informe um valor válido.');await api('/api/personal/entries','POST',{kind:modal.value,title:form.value.title,body:form.value.body,category:form.value.category,day:form.value.day,direction:form.value.direction,amount_cents:modal.value==='transaction'?cents:0,target:modal.value==='goal'?Number(form.value.target):1,domain:form.value.domain,place:form.value.place});notify('Registro salvo.')}modal.value=null;await refresh();previousFocus?.focus?.()}catch(e){notify(e.message,'error')}finally{saving.value=false}}
async function toggleHabit(item){if(saving.value)return;saving.value=true;try{const result=await api(`/api/personal/entries/${encodeURIComponent(item.id)}/checkin`,'PUT',{done:!isDone(item.id)});data.value={...data.value,...result};notify(isDone(item.id)?'Passo de hoje registrado.':'Registro de hoje desmarcado.')}catch(e){notify(e.message,'error')}finally{saving.value=false}}
async function finish(task){if(saving.value)return;saving.value=true;try{await completeTask(task.id);notify('Tarefa concluída. Seu progresso também chega à cidade.');await refresh()}catch(e){notify(e.message,'error')}finally{saving.value=false}}
function showProof(item){previousFocus=document.activeElement;proofDialog.value={item,note:'',file:null,preview:''};nextTick(()=>document.querySelector('.proof-dialog textarea')?.focus())}
function closeProof(){if(proofSaving.value)return;if(proofDialog.value?.preview)URL.revokeObjectURL(proofDialog.value.preview);proofDialog.value=null;previousFocus?.focus?.()}
function pickPhoto(event){const file=event.target.files?.[0];if(!file)return;if(proofDialog.value.preview)URL.revokeObjectURL(proofDialog.value.preview);proofDialog.value={...proofDialog.value,file,preview:URL.createObjectURL(file)}}
const hasBuilding=id=>(data.value.predios||[]).includes(id)
async function buildFor(item){if(saving.value)return;saving.value=true;try{const city=await api('/api/city');await api('/api/city/actions','POST',{type:'build',activity_id:item.id,expected_revision:city.revision,request_id:crypto.randomUUID()});data.value={...data.value,predios:[...(data.value.predios||[]),item.id]};notify(`Prédio "${item.place||item.title}" construído na cidade.`);await refresh()}catch(e){notify(e.message,'error')}finally{saving.value=false}}
async function sendProof(){const dialog=proofDialog.value;if(!dialog||proofSaving.value)return;const note=dialog.note.trim();if(!dialog.file&&note.length<20){notify('Escreva pelo menos 20 caracteres ou envie uma foto.','error');return}proofSaving.value=true;try{const proof={};if(note)proof.note=note;if(dialog.file)proof.photo=await photoToDataUrl(dialog.file);const result=await api(`/api/personal/entries/${encodeURIComponent(dialog.item.id)}/checkin`,'PUT',{done:true,proof});const {proof_result,...rest}=result;data.value={...data.value,...rest};notify(proof_result?.bonus>0?`Comprovado · +${proof_result.bonus} moedas`:proof_result?.reason==='daily_cap'?'Comprovação guardada. O bônus de hoje já foi usado.':'Comprovação atualizada.');if(dialog.preview)URL.revokeObjectURL(dialog.preview);proofDialog.value=null;previousFocus?.focus?.()}catch(e){notify(e.message,'error')}finally{proofSaving.value=false}}
function openBridge(label,path){if(!path.startsWith('/#/'))return;previousFocus=document.activeElement;bridge.value={label,url:'http://127.0.0.1:8765'+path};bridgeLoading.value=true;clearTimeout(bridgeTimer);bridgeTimer=setTimeout(()=>bridgeLoading.value=false,12000);nextTick(()=>document.querySelector('.bridge-close')?.focus())}
function closeBridge(){bridge.value=null;clearTimeout(bridgeTimer);previousFocus?.focus?.();refresh()}
function openDocument(item){openBridge(item.name||item.filename||'Seu material','/#/documentos')}
function keydown(event){if(event.key==='Escape'){if(bridge.value)closeBridge();else if(proofDialog.value)closeProof();else if(modal.value)closeForm();else mobileMenu.value=false}if(event.key==='Tab'&&(bridge.value||modal.value||proofDialog.value)){const root=document.querySelector(proofDialog.value?'.proof-dialog':modal.value?'.entry-dialog':'.bridge-dialog');const els=[...root.querySelectorAll('button:not(:disabled),input,select,textarea,iframe,a[href]')];if(event.shiftKey&&document.activeElement===els[0]){event.preventDefault();els.at(-1)?.focus()}else if(!event.shiftKey&&document.activeElement===els.at(-1)){event.preventDefault();els[0]?.focus()}}}
onMounted(()=>{parseRoute();refresh();window.addEventListener('hashchange',parseRoute);window.addEventListener('keydown',keydown);poll=setInterval(()=>{if(!document.hidden&&!modal.value&&!bridge.value)refresh()},60000)})
onUnmounted(()=>{clearInterval(poll);clearTimeout(timer);clearTimeout(bridgeTimer);window.removeEventListener('hashchange',parseRoute);window.removeEventListener('keydown',keydown)})
</script>
<template>
<main class="personal-app" :class="{ 'sidebar-compact':collapsed,'mobile-nav-open':mobileMenu }">
  <button v-if="mobileMenu" class="nav-scrim" aria-label="Fechar menu" @click="mobileMenu=false" />
  <aside class="sidebar">
    <a class="personal-brand" href="#/inicio" aria-label="Cityou, seu dia"><span class="personal-mark">c<span>.</span></span><strong>Cityou<span>seu espaço pessoal</span></strong></a>
    <button class="sidebar-toggle" :aria-label="collapsed?'Expandir menu':'Recolher menu'" @click="collapsed=!collapsed"><Icon name="menu" :size="16" /></button>
    <nav aria-label="Funções do Cityou"><div v-for="group in groups" :key="group" class="nav-group"><span class="nav-group-label">{{ group }}</span><a v-for="item in sections.filter(i=>i.group===group)" :key="item.id" :href="`#/${item.id}`" :aria-label="item.label" class="personal-nav-item" :class="{active:route===item.id}" :aria-current="route===item.id?'page':undefined" :title="collapsed?item.label:undefined"><Icon :name="item.icon" :size="19" /><span>{{ item.label }}</span><small v-if="item.id==='tarefas'&&pending.length">{{ pending.length }}</small></a></div></nav>
    <div class="sidebar-bottom"><a href="#/mundo" class="city-link" :class="{active:route==='mundo'}"><span class="city-link-icon"><Icon name="globe" :size="22" /></span><span><strong>Mapa-mundo</strong><small>Suas viagens, passo a passo</small></span><Icon name="arrow" :size="15" /></a><a href="#/cidade" class="city-link" :class="{active:route==='cidade'}"><span class="city-link-icon"><Icon name="city" :size="22" /></span><span><strong>Minha cidade</strong><small>O reflexo do seu progresso</small></span><Icon name="arrow" :size="15" /></a><button class="profile-link" @click="openBridge('Configurações','/#/configuracoes')"><span class="profile-avatar">L</span><span><strong>Luiz Felipe</strong><small>Seu espaço, no seu ritmo</small></span><Icon name="settings" :size="17" /></button></div>
  </aside>
  <section class="app-main">
    <header class="personal-topbar"><div class="topbar-left"><button class="mobile-menu icon-btn" aria-label="Abrir menu" @click="mobileMenu=!mobileMenu"><Icon name="menu" /></button><span class="breadcrumb">Meu espaço <Icon name="chevron" :size="13" /><strong>{{ active?.label||(route==='mundo'?'Mapa-mundo':'Minha cidade') }}</strong></span></div><div class="topbar-actions"><span class="local-status"><i :class="{offline:!connected}" />{{ connected?'Conectado ao Fifones':'Fonte original offline' }}</span><button class="icon-btn" aria-label="Atualizar meus dados" :disabled="refreshing" @click="refresh"><Icon name="refresh" :class="{spinning:refreshing}" :size="18" /></button><button class="new-entry" @click="showForm(route==='habitos'?'habit':route==='metas'?'goal':route==='financas'?'transaction':route==='nutricao'?'meal':route==='memorias'||route==='autoconhecimento'?'note':'task')"><Icon name="plus" :size="17" /><span>Novo registro</span></button></div></header>
    <div v-if="error && route !== 'mundo'" class="page-error" role="alert">{{ error }}<button @click="refresh">Tentar novamente</button></div>
    <div v-if="route==='mundo'" class="city-space"><div class="city-space-bar"><span><Icon name="globe" :size="17" />Seu mapa-mundo, em um espaço próprio.</span><a href="/world.html" target="_blank" rel="noopener">Abrir só o mapa <Icon name="arrow" :size="15" /></a></div><iframe src="/world.html" title="Mapa-mundo BuildU" /></div>
    <div v-else-if="route==='cidade'" class="city-space"><div class="city-space-bar"><span><Icon name="city" :size="17" />Sua cidade, em um espaço próprio.</span><a href="/city.html" target="_blank" rel="noopener">Abrir só a cidade <Icon name="arrow" :size="15" /></a></div><iframe src="/city.html" title="Minha cidade Cityou" /></div>
    <div v-else class="personal-content">
      <div class="page-heading"><div><span class="date-caption">{{ shortDate }}</span><h1>{{ route==='inicio'?greeting:active?.label }}</h1><p>{{ route==='inicio'?'Sua vida não precisa caber toda na sua cabeça.':active?.description }}</p></div><button v-if="route!=='inicio'" class="quiet-button" @click="openBridge('Conversar com Fifones','/#/conversa')"><Icon name="mic" :size="17" />Falar sobre isso</button><span v-else class="greeting-orbit" aria-hidden="true"><i v-for="n in 6" :key="n" :style="{'--petal':n}" /><Icon name="spark" :size="23" /></span></div>
      <p v-if="routeSource && data.sources[routeSource]?.connected===false" class="source-notice" role="status">Esta fonte está indisponível no momento. Seus dados anteriores continuam preservados.</p>
      <div v-if="loading" class="loading-state" role="status"><Icon name="refresh" class="spinning" />Abrindo seu espaço…</div>
      <template v-else-if="route==='inicio'">
        <section class="capture-panel"><span class="capture-symbol"><Icon name="spark" :size="25" /></span><div><h2>O que vamos tirar da sua cabeça?</h2><p>Uma tarefa, uma ideia ou algo que você quer lembrar.</p></div><button class="capture-button" @click="showForm('note')">Anotar <Icon name="plus" :size="17" /></button><button class="voice-button" aria-label="Abrir conversa por voz com Fifones" @click="openBridge('Conversa por voz','/#/conversa')"><Icon name="mic" :size="20" /></button></section>
        <div class="overview-grid">
          <section class="surface today-panel"><div class="surface-heading"><h2>Seu próximo passo</h2><a href="#/tarefas">Ver tarefas <Icon name="arrow" :size="15" /></a></div><div class="week-strip"><span v-for="d in weeks" :key="d.day" :class="{today:d.today}"><small>{{ d.label }}</small><strong>{{ d.num }}</strong><i v-if="d.today" /></span></div><ul v-if="pending.length" class="personal-task-list"><li v-for="task in pending.slice(0,3)" :key="task.id"><button class="round-check" :aria-label="`Concluir ${task.title}`" :disabled="saving" @click="finish(task)" /><div><strong>{{ task.title }}</strong><small>{{ task.due_date?formatDate(task.due_date):'No seu tempo' }}</small></div><span class="priority-dot" :class="`priority-${task.priority}`" /></li></ul><div v-else class="gentle-empty"><span class="empty-orbit"><Icon name="check" :size="24" /></span><strong>{{ connected?'Espaço para o que vem agora.':'Suas tarefas estão no Fifones original.' }}</strong><p>{{ connected?'Escolha uma tarefa pequena para começar.':'Reconecte a fonte para ver suas tarefas.' }}</p><button class="inline-button" @click="showForm('task')"><Icon name="plus" :size="15" />Criar uma tarefa</button></div></section>
          <section class="surface day-agenda"><div class="surface-heading"><h2>Na sua agenda</h2><a href="#/agenda"><Icon name="arrow" :size="17" /></a></div><div class="agenda-summary"><span class="agenda-day">{{ today().slice(-2) }}</span><div><strong>{{ todayEvents.length }} compromisso{{ todayEvents.length===1?'':'s' }}</strong><small>para hoje</small></div><Icon name="calendar" :size="28" /></div><div v-for="event in todayEvents.slice(0,2)" :key="event.id" class="small-event"><time>{{ formatTime(event.start_at) }}</time><strong>{{ event.title }}</strong></div><div v-if="!todayEvents.length" class="agenda-empty"><span class="agenda-doodle" aria-hidden="true"><Icon name="sun" :size="42" /></span><p>{{ data.sources.events?.connected?'Um pouco de espaço livre também faz parte.':'Agenda indisponível no momento.' }}</p></div><button class="quiet-button full-width" @click="openBridge('Agenda','/#/agenda')"><Icon name="plus" :size="15" />Adicionar compromisso</button></section>
        </div>
        <div class="section-label"><h2>Um pouco melhor, todos os dias</h2><span>Seu ritmo conta.</span></div>
        <div class="area-grid"><a v-for="card in areaCards" :key="card.id" :href="`#/${card.id}`" class="area-card" :class="card.tone"><span class="area-icon"><Icon :name="card.icon" :size="23" /></span><span class="area-kicker">{{ card.title }}</span><strong>{{ card.value }}</strong><small>{{ card.detail }}</small><Icon name="arrow" :size="18" class="area-arrow" /></a></div>
        <section class="reflection-strip"><span class="reflection-icon"><Icon name="heart" :size="22" /></span><div><strong>E você, como está hoje?</strong><span>Uma pausa para perceber. Só isso.</span></div><button class="quiet-button" @click="navigate('autoconhecimento')">Registrar meu momento <Icon name="arrow" :size="15" /></button></section>
      </template>
      <template v-else-if="route==='tarefas'">
        <div class="list-toolbar"><div class="segmented"><button v-for="filter in [{id:'open',label:'A fazer'},{id:'done',label:'Concluídas'},{id:'all',label:'Todas'}]" :key="filter.id" :class="{active:taskFilter===filter.id}" @click="taskFilter=filter.id">{{ filter.label }}</button></div><label class="search-field"><Icon name="search" :size="17" /><input v-model="search" placeholder="Buscar tarefa" aria-label="Buscar tarefa" /></label><button class="primary-btn" @click="showForm('task')"><Icon name="plus" :size="17" />Nova tarefa</button></div><section class="surface"><ul class="personal-task-list full-list"><li v-for="task in shownTasks" :key="task.id"><button class="round-check" :class="{done:task.status==='done'}" :disabled="saving||task.status==='done'" :aria-label="`Concluir ${task.title}`" @click="finish(task)"><Icon v-if="task.status==='done'" name="check" :size="14" /></button><div><strong>{{ task.title }}</strong><small>{{ task.description||'Sem descrição' }}</small></div><span class="task-date">{{ formatDate(task.due_date) }}</span></li></ul><div v-if="!shownTasks.length" class="gentle-empty"><Icon name="tasks" :size="35" /><h2>Nada nesta lista.</h2><p>Adicione o próximo passo quando precisar.</p></div></section>
      </template>
      <template v-else-if="route==='habitos'">
        <div class="habits-summary surface"><span class="habit-ring" :style="{'--progress':habits.length?`${habitsDone/habits.length*100}%`:'0%'}"><strong>{{ habitsDone }}<small>/ {{ habits.length }}</small></strong></span><div><h2>Hoje já conta.</h2><p>{{ habits.length?'Registre o que você fez, sem precisar ser perfeito.':'Escolha algo pequeno o suficiente para caber no dia.' }}</p></div><button class="primary-btn" @click="showForm('habit')"><Icon name="plus" :size="17" />Novo hábito</button></div><div class="record-grid"><article v-for="habit in habits" :key="habit.id" class="surface habit-card" :class="{completed:isDone(habit.id)}"><span class="area-icon mint"><Icon name="habits" :size="24" /></span><h2>{{ habit.title }}</h2><p>{{ habit.body||'Seu passo possível para hoje.' }}</p><small v-if="habit.place" class="place-tag">{{ habit.place }}</small><button class="habit-done" :disabled="saving" :aria-pressed="isDone(habit.id)" @click="toggleHabit(habit)"><Icon :name="isDone(habit.id)?'check':'plus'" :size="18" />{{ isDone(habit.id)?'Feito hoje':'Marcar como feito' }}</button><button type="button" class="proof-button" :disabled="saving" @click="showProof(habit)"><Icon name="spark" :size="15" />Comprovar</button><button v-if="!hasBuilding(habit.id)" type="button" class="proof-button" :disabled="saving" @click="buildFor(habit)"><Icon name="city" :size="15" />Construir na cidade</button><a v-else class="building-tag" href="#/cidade"><Icon name="city" :size="15" />Prédio na cidade</a></article><button class="add-card" @click="showForm('habit')"><Icon name="plus" :size="27" /><strong>Criar meu próximo hábito</strong><span>Comece pequeno.</span></button></div>
      </template>
      <template v-else-if="route==='metas'">
        <div class="list-toolbar"><span class="muted">Um passo concreto por dia. Sem prazo de validade.</span><button class="primary-btn" @click="showForm('goal')"><Icon name="plus" :size="17" />Nova meta</button></div>
        <div class="record-grid"><article v-for="goal in goals" :key="goal.id" class="surface habit-card"><span class="area-icon purple"><Icon name="spark" :size="24" /></span><h2>{{ goal.title }}</h2><p>{{ goal.body }}</p><span class="goal-caption">{{ Math.min(goalCount(goal.id),goal.target) }} / {{ goal.target }} dias com progresso</span><span class="personal-goal-track"><i :style="{transform:`scaleX(${Math.min(1,goalCount(goal.id)/goal.target)})`}" /></span><small v-if="goal.place" class="place-tag">{{ goal.place }}</small><button class="habit-done" :disabled="saving" :aria-pressed="isDone(goal.id)" @click="toggleHabit(goal)"><Icon :name="isDone(goal.id)?'check':'plus'" :size="17" />{{ isDone(goal.id)?'Passo de hoje registrado':'Registrar um passo hoje' }}</button><button type="button" class="proof-button" :disabled="saving" @click="showProof(goal)"><Icon name="spark" :size="15" />Comprovar</button><button v-if="!hasBuilding(goal.id)" type="button" class="proof-button" :disabled="saving" @click="buildFor(goal)"><Icon name="city" :size="15" />Construir na cidade</button><a v-else class="building-tag" href="#/cidade"><Icon name="city" :size="15" />Prédio na cidade</a></article><button class="add-card" @click="showForm('goal')"><Icon name="spark" :size="27" /><strong>Qual é sua próxima conquista?</strong><span>Você define o que importa.</span></button></div>
      </template>
      <template v-else-if="route==='agenda'">
        <div class="list-toolbar"><span class="muted">Compromissos deste mês</span><button class="primary-btn" @click="openBridge('Novo compromisso','/#/agenda')"><Icon name="plus" :size="17" />Novo compromisso</button></div><div class="record-grid"><article v-for="event in upcoming" :key="event.id" class="surface event-card"><span class="event-date">{{ formatDate(event.start_at) }}</span><h2>{{ event.title }}</h2><p>{{ formatTime(event.start_at) }} — {{ formatTime(event.end_at) }}</p><span>{{ event.location||'Local não informado' }}</span><button class="inline-button" @click="openBridge(event.title,'/#/agenda')">Ver compromisso <Icon name="arrow" :size="15" /></button></article></div><div v-if="!upcoming.length" class="surface gentle-empty"><Icon name="calendar" :size="40" /><h2>{{ data.sources.events?.connected?'Sua agenda tem espaço.':'Não foi possível carregar a agenda.' }}</h2><p>Os compromissos salvos continuam no seu Fifones.</p><button class="primary-btn" @click="openBridge('Agenda','/#/agenda')">Abrir agenda completa</button></div>
      </template>

      <template v-else-if="route==='financas'">
        <div class="finance-stats"><article class="surface"><span>Entradas do mês</span><strong class="mint-text">{{ money(income) }}</strong><Icon name="down" :size="20" /></article><article class="surface"><span>Saídas do mês</span><strong class="peach-text">{{ money(expenses) }}</strong><Icon name="up" :size="20" /></article><article class="surface"><span>Saldo dos registros</span><strong>{{ money(income-expenses) }}</strong><Icon name="finance" :size="20" /></article></div><div class="list-toolbar"><h2>Seus lançamentos</h2><button class="primary-btn" @click="showForm('transaction')"><Icon name="plus" :size="17" />Novo lançamento</button><button class="quiet-button" @click="openBridge('Planilhas e finanças','/#/financas')">Minhas planilhas <Icon name="arrow" :size="15" /></button></div><section class="surface"><div v-for="item in transactions" :key="item.id" class="transaction-row"><span class="transaction-icon" :class="item.direction"><Icon :name="item.direction==='income'?'down':'up'" :size="18" /></span><div><strong>{{ item.title }}</strong><small>{{ formatDate(item.day) }} · {{ item.category }}</small></div><strong :class="item.direction==='income'?'mint-text':'peach-text'">{{ item.direction==='income'?'+':'−' }} {{ money(item.amount_cents) }}</strong></div><div v-if="!transactions.length" class="gentle-empty"><Icon name="finance" :size="36" /><h2>Comece com um lançamento.</h2><p>Este saldo considera apenas os registros deste novo espaço.<br />Suas planilhas anteriores continuam disponíveis.</p><button class="inline-button" @click="showForm('transaction')">Adicionar entrada ou saída <Icon name="plus" :size="15" /></button></div></section>
      </template>
      <template v-else-if="route==='fitness'">
        <div class="fitness-hero surface"><span class="area-icon peach"><Icon name="fitness" :size="30" /></span><div><span class="eyebrow">SUA HISTÓRIA CONTINUA AQUI</span><h2>Voltar a cuidar de você.</h2><p>Seu perfil, avaliação e acompanhamento estão preservados.</p></div><button class="primary-btn" @click="openBridge('Avaliação Fitness e voz Gemini','/#/fitness')">Continuar avaliação <Icon name="arrow" :size="17" /></button></div><div class="finance-stats"><article class="surface"><span>Última pesagem</span><strong>{{ fitness.weights?.length?`${fitness.weights[0].kg} kg`:'Ainda sem registro' }}</strong></article><article class="surface"><span>Pesagens registradas</span><strong>{{ fitness.weights?.length||0 }}</strong></article><article class="surface"><span>Retornos registrados</span><strong>{{ fitness.checkins?.length||0 }}</strong></article></div><section class="surface weight-list"><div class="surface-heading"><h2>Sua evolução</h2><button class="inline-button" @click="openBridge('Registrar peso','/#/fitness')">Registrar peso <Icon name="plus" :size="15" /></button></div><div v-for="weight in (fitness.weights||[]).slice(0,7)" :key="weight.day" class="transaction-row"><span>{{ formatDate(weight.day) }}</span><strong>{{ weight.kg }} kg</strong><small>{{ weight.note }}</small></div><div v-if="!fitness.weights?.length" class="gentle-empty"><Icon name="fitness" :size="32" /><p>Seu gráfico começa com a primeira pesagem.</p></div></section>
      </template>
      <template v-else-if="route==='nutricao'">
        <section class="nutrition-banner surface"><span class="nutrition-art" aria-hidden="true"><i /><i /><i /></span><div><span class="eyebrow">UM OLHAR PARA SUA ALIMENTAÇÃO</span><h2>Primeiro, conhecer sua rotina.</h2><p>Registre refeições, horários e quantidades. Nenhum nutriente é estimado sem informação suficiente.</p><button class="primary-btn" @click="showForm('meal')"><Icon name="plus" :size="17" />Registrar refeição</button></div></section><div class="record-grid"><article v-for="item in entryList('meal')" :key="item.id" class="surface note-card"><span class="eyebrow">{{ formatDate(item.day) }}</span><h2>{{ item.title }}</h2><p>{{ item.body }}</p></article></div><button class="quiet-button" @click="openBridge('Alimentação na avaliação','/#/fitness')">Continuar entrevista sobre alimentação <Icon name="arrow" :size="16" /></button>
      </template>
      <template v-else-if="route==='autoconhecimento'">
        <section class="reflection-hero surface"><span class="reflection-bloom" aria-hidden="true"><i v-for="n in 5" :key="n" :style="{'--petal':n}" /></span><div><span class="eyebrow">UMA CONVERSA COM VOCÊ</span><h2>Como está sendo o seu dia?</h2><p>Escreva o que sente, o que funcionou ou o que está difícil.</p><div class="hero-actions"><button class="primary-btn" @click="showForm('note')">Registrar meu momento <Icon name="plus" :size="17" /></button><button class="quiet-button" @click="openBridge('Conversar com Fifones','/#/conversa')"><Icon name="mic" :size="17" />Conversar</button></div></div></section><div class="section-label"><h2>Seus registros</h2><a href="#/memorias">Ver memórias <Icon name="arrow" :size="15" /></a></div><div class="record-grid"><article v-for="note in notes.slice(0,6)" :key="note.id" class="surface note-card"><span class="eyebrow">{{ formatDate(note.day) }}</span><h2>{{ note.title }}</h2><p>{{ note.body }}</p></article></div><p v-if="!notes.length" class="small-note">Você escolhe o que compartilhar. Seus registros ficam neste computador.</p>
      </template>
      <template v-else-if="route==='biblioteca'||route==='estudos'">
        <section v-if="route==='estudos'" class="study-banner surface"><span class="area-icon blue"><Icon name="study" :size="30" /></span><div><h2>Um professor ao seu lado.</h2><p>Use seus documentos para ler, perguntar e treinar apresentações.</p></div><button class="primary-btn" @click="openBridge('Professor Fifones','/#/professor')">Abrir professor <Icon name="arrow" :size="16" /></button></section><div class="list-toolbar"><label class="search-field"><Icon name="search" :size="17" /><input v-model="search" placeholder="Buscar nos seus materiais" aria-label="Buscar materiais" /></label><button class="primary-btn" @click="openBridge('Adicionar material','/#/documentos')"><Icon name="plus" :size="17" />Adicionar material</button></div><div class="document-grid"><button v-for="doc in filteredDocs" :key="doc.id" class="document-card" @click="openDocument(doc)"><span class="document-cover"><img v-if="!failedCovers[doc.id]" :src="`/api/personal/documents/${encodeURIComponent(doc.id)}/cover`" alt="" loading="lazy" @error="failedCovers={...failedCovers,[doc.id]:true}" /><Icon :name="/xlsx|xls|csv/i.test(doc.filename||doc.name||'')?'finance':'study'" :size="44" /><span>{{ (doc.name||doc.filename||doc.title||'Material').split('.').at(-1).toUpperCase().slice(0,5) }}</span></span><strong>{{ doc.name||doc.filename||doc.title||'Sem título' }}</strong><small>Ver no leitor Fifones <Icon name="arrow" :size="13" /></small></button></div><div v-if="!filteredDocs.length" class="surface gentle-empty"><Icon name="library" :size="38" /><h2>{{ data.sources.documents?.connected?'Seus próximos conhecimentos começam aqui.':'Biblioteca indisponível no momento.' }}</h2><p>Os materiais anteriores continuam na Biblioteca original.</p></div>
      </template>
      <template v-else-if="route==='projetos'">
        <div class="list-toolbar"><span class="muted">{{ projects.length }} projetos no seu Fifones</span><button class="primary-btn" @click="openBridge('Projetos','/#/projetos')"><Icon name="plus" :size="17" />Gerenciar projetos</button></div><div class="record-grid"><button v-for="project in projects" :key="project.id" class="surface project-card" @click="openBridge(project.name,`/#/projetos/${encodeURIComponent(project.id)}`)"><span class="project-cover"><Icon name="projects" :size="40" /><i /><i /></span><h2>{{ project.name||'Seu projeto' }}</h2><p>{{ project.description||'Tarefas, mapas e materiais conectados.' }}</p><span class="inline-button">Entrar no projeto <Icon name="arrow" :size="16" /></span></button></div><div v-if="!projects.length" class="surface gentle-empty"><Icon name="projects" :size="40" /><h2>Seu próximo projeto tem espaço aqui.</h2><button class="inline-button" @click="openBridge('Projetos','/#/projetos')">Abrir meus projetos</button></div>
      </template>
      <template v-else-if="route==='memorias'">
        <div class="list-toolbar"><span class="muted">Suas anotações e o contexto que você já compartilhou.</span><button class="primary-btn" @click="showForm('note')"><Icon name="plus" :size="17" />Nova memória</button><button class="quiet-button" @click="openBridge('Memórias e Obsidian','/#/memoria')">Memórias e Obsidian <Icon name="arrow" :size="15" /></button></div><div class="record-grid"><article v-for="note in notes" :key="note.id" class="surface note-card"><span class="eyebrow">{{ formatDate(note.day) }} · NOVO ESPAÇO</span><h2>{{ note.title }}</h2><p>{{ note.body }}</p></article><article v-for="memory in memories.slice(0,30)" :key="memory.id" class="surface note-card"><span class="eyebrow">{{ memory.category||'SEU CONTEXTO' }} · FIFONES</span><p>{{ memory.content }}</p></article></div><div v-if="!notes.length&&!memories.length" class="surface gentle-empty"><Icon name="note" :size="38" /><h2>Guarde uma ideia.</h2><p>Você pode começar com uma frase.</p></div>
      </template>
    </div>
  </section>

  <Transition name="notice"><div v-if="notice" class="personal-notice" :class="notice.kind" role="status"><Icon :name="notice.kind==='error'?'close':'check'" :size="18" /><span>{{ notice.text }}</span><button class="icon-btn" aria-label="Fechar aviso" @click="notice=''"><Icon name="close" :size="15" /></button></div></Transition>
  <div v-if="modal" class="personal-overlay" @click.self="closeForm"><form class="entry-dialog" role="dialog" aria-modal="true" aria-labelledby="entry-title" @submit.prevent="save"><header><span class="dialog-icon"><Icon :name="modal==='task'?'tasks':modal==='habit'?'habits':modal==='goal'?'spark':modal==='transaction'?'finance':modal==='meal'?'nutrition':'note'" :size="23" /></span><button type="button" class="icon-btn" aria-label="Fechar formulário" :disabled="saving" @click="closeForm"><Icon name="close" /></button></header><h2 id="entry-title">{{ {task:'Um próximo passo.',habit:'Um hábito possível.',goal:'Uma conquista de cada vez.',note:'Tire da cabeça.',transaction:'Seu dinheiro, com clareza.',meal:'O que teve no prato?'}[modal] }}</h2><label>{{ modal==='task'?'O que você quer fazer?':modal==='habit'?'Qual hábito quer cultivar?':'Título' }}<input v-model="form.title" required maxlength="180" :placeholder="modal==='habit'?'Algo que caiba em dois minutos':'Escreva aqui'" /></label><label v-if="['habit','goal','task'].includes(modal)">Área<select v-model="form.domain"><option v-for="[id,name] in domains" :key="id" :value="id">{{ name }}</option></select></label><label v-if="['habit','goal','task'].includes(modal)">Local ou atividade, se houver<input v-model="form.place" maxlength="80" placeholder="Ex.: Academia Central" /></label><label v-if="modal==='task'">Prazo, se houver<input v-model="form.due_date" type="date" /></label><template v-else><div v-if="modal==='transaction'" class="form-columns"><label>Tipo<select v-model="form.direction" aria-label="Tipo"><option value="expense">Saída</option><option value="income">Entrada</option></select></label><label>Valor em R$<input v-model="form.amount" type="text" inputmode="decimal" placeholder="0,00" required /></label></div><label v-if="modal==='transaction'">Categoria<input v-model="form.category" maxlength="50" /></label><label>{{ modal==='meal'?'Alimentos e quantidades':'Detalhes, se quiser' }}<textarea v-model="form.body" rows="4" maxlength="4000" :placeholder="modal==='meal'?'O que comeu, como foi preparado e qual a quantidade aproximada':'Deixe aqui o que importa para você.'" /></label><label v-if="modal==='goal'">Quantos dias com um passo concreto?<input v-model="form.target" type="number" min="1" max="10000" required /></label><label>Data<input v-model="form.day" required type="date" /></label></template><footer><button type="button" class="quiet-button" :disabled="saving" @click="closeForm">Agora não</button><button class="primary-btn" :disabled="saving">{{ saving?'Salvando…':'Guardar' }}<Icon name="check" :size="16" /></button></footer></form></div>
  <div v-if="proofDialog" class="personal-overlay" @click.self="closeProof"><form class="entry-dialog proof-dialog" role="dialog" aria-modal="true" aria-labelledby="proof-title" @submit.prevent="sendProof"><header><span class="dialog-icon"><Icon name="check" :size="23" /></span><button type="button" class="icon-btn" aria-label="Fechar comprovação" :disabled="proofSaving" @click="closeProof"><Icon name="close" /></button></header><h2 id="proof-title">Comprovar: {{ proofDialog.item.title }}</h2><p class="proof-help">Opcional. Um relato ou uma foto rende +5 moedas, até 3 por dia. Só você vê. Marcar sem comprovar continua valendo.</p><label>O que você fez?<textarea v-model="proofDialog.note" rows="4" maxlength="500" placeholder="Pelo menos 20 caracteres, ou envie uma foto" /></label><label class="photo-field">Foto, se quiser<input type="file" accept="image/*" capture="environment" @change="pickPhoto" /></label><img v-if="proofDialog.preview" class="proof-preview" :src="proofDialog.preview" alt="Prévia da foto escolhida" /><footer><button type="button" class="quiet-button" :disabled="proofSaving" @click="closeProof">Agora não</button><button class="primary-btn" :disabled="proofSaving">{{ proofSaving?'Enviando…':'Guardar comprovação' }}<Icon name="check" :size="16" /></button></footer></form></div>
  <div v-if="bridge" class="personal-overlay bridge-overlay"><section class="bridge-dialog" role="dialog" aria-modal="true" :aria-label="bridge.label"><header><span><span class="bridge-mark">c.</span><strong>{{ bridge.label }}</strong><small>Seu Fifones original · dados preservados</small></span><button class="icon-btn bridge-close" aria-label="Voltar ao Cityou" @click="closeBridge"><Icon name="close" :size="22" /></button></header><div v-if="!connected" class="gentle-empty"><Icon name="link" :size="40" /><h2>Vamos reconectar.</h2><p>Abra o Fifones original na porta 8765 para usar este recurso.</p><button class="primary-btn" @click="refresh">Verificar conexão</button></div><template v-else><span v-if="bridgeLoading" class="bridge-loading" role="status">Abrindo seu espaço…</span><iframe :src="bridge.url" :title="bridge.label" allow="microphone; camera" @load="bridgeLoading=false" /></template></section></div>
</main>
</template>
